  async function fetchJson(url) {
    try {
      const r = await fetch(url);
      if (!r.ok) throw new Error('HTTP ' + r.status);
      const ct = r.headers.get('content-type') || '';
      if (ct.includes('application/json') || ct.includes('text/json')) {
        return await r.json();
      }
      const txt = await r.text();
      try { return JSON.parse(txt); } catch (e) { return txt; }
    } catch (err) {
      console.warn('Fetch failed, will use embedded fallback if available:', err);
      return null;
    }
  }

  function extractArray(obj, key) {
    if (!obj) return null;
    if (Array.isArray(obj)) return obj;
    if (key && Array.isArray(obj[key])) return obj[key];
    for (const k in obj) {
      if (Array.isArray(obj[k])) return obj[k];
    }
    return null;
  }

  function normalizeSource(item) {
    if (!item) return null;
    if (typeof item === 'string') return { value: item, label: item };
    const value = item.sourceCode || item.code || item.key || item.id || item.value || item.plateSourceCode || item.plateSrcCode || item.name;
    const label = item.name || item.plateSourceName || item.displayName || item.description || item.text || item.label || value;
    return { value: String(value || ''), label: String(label || '') };
  }

  function normalizePlate(item) {
    if (!item) return null;
    if (typeof item === 'string') return { value: item, label: item };
    const value = item.plateCode || item.code || item.value || item.id || item.name;
    // Check item.label FIRST before falling back to other fields
    const label = item.label || item.plateCode || item.code || item.name || item.value || value;
    return { value: String(value || ''), label: String(label || '') };
  }

  function createSelect(id) {
    const select = document.createElement('select');
    select.id = id;
    select.style.minWidth = '100%';
    select.style.marginTop = '6px';
    select.style.padding = '10px 12px';
    select.style.fontSize = '1rem';
    select.style.border = '1px solid #ccc';
    select.style.borderRadius = '6px';
    select.style.background = '#fff';
    return select;
  }

  function replaceInput(input, select) {
    if (!input || !select) return null;
    const wrapper = input.closest('.MuiAutocomplete-root') || input.parentElement;
    if (!wrapper) return null;
    input.disabled = false;
    // hide original autocomplete wrapper and insert our select in its place
    wrapper.style.display = 'none';
    // insert before the wrapper so the select remains visible and correctly positioned
    wrapper.parentNode.insertBefore(select, wrapper);
    return select;
  }

  function setInputValue(input, value) {
    if (!input) return;
    input.value = value || '';
    const event = new Event('input', { bubbles: true });
    input.dispatchEvent(event);
  }

  function setSelectOptions(select, items, placeholder) {
    select.innerHTML = '';
    const empty = document.createElement('option');
    empty.value = '';
    empty.textContent = placeholder || 'Select';
    empty.disabled = true;
    empty.selected = true;
    select.appendChild(empty);
    items.forEach(item => {
      if (!item || !item.value) return;
      const option = document.createElement('option');
      option.value = item.value;
      option.textContent = item.label || item.value;
      select.appendChild(option);
    });
  }

  function showError(select, message) {
    select.innerHTML = '';
    const option = document.createElement('option');
    option.value = '';
    option.textContent = message || 'Error';
    option.disabled = true;
    option.selected = true;
    select.appendChild(option);
  }

  // Initialize Page
  function init() {
    const sourceInput = document.querySelector('input[name="plateSrcCode"]');
    const codeInput = document.querySelector('input[name="plateCodeId"]');
    const plateNoInput = document.querySelector('input[name="plateNo"]');
    if (!sourceInput || !codeInput || !plateNoInput) return;

    const sourceSelect = createSelect('plateSourceSelect');
    const codeSelect = createSelect('plateCodeSelect');
    codeSelect.disabled = true;
    replaceInput(sourceInput, sourceSelect);
    replaceInput(codeInput, codeSelect);

    // Find the form container that wraps all plate fields
    let formContainer = sourceInput.closest('[class*="MuiCard"]') || 
                        sourceInput.closest('[class*="MuiPaper"]') ||
                        plateNoInput.closest('[class*="MuiCard"]') ||
                        plateNoInput.closest('[class*="MuiPaper"]') ||
                        sourceInput.parentElement.parentElement.parentElement;

    // Create a separate container for Licence fields
    let licenceContainer = null;
    if (formContainer) {
      licenceContainer = document.createElement('div');
      licenceContainer.style.display = 'none';
      licenceContainer.className = formContainer.className;
      licenceContainer.innerHTML = `
        <div class="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div class="MuiBox-root mui-0">
            <label class="MuiFormLabel-root MuiInputBase-formLabel MuiFormLabel-colorPrimary MuiFormLabel-filled">Licence Issuing Authority</label>
            <div class="MuiAutocomplete-root MuiAutocomplete-fullWidth MuiAutocomplete-hasPopupIcon" style="margin-top: 8px;">
              <select id="licenceSourceSelect" style="width: 100%; padding: 12px; border: 1px solid #ccc; border-radius: 4px; font-size: 14px;">
                <option value="">Select licence issuing authority</option>
              </select>
            </div>
          </div>
          <div class="MuiBox-root mui-0">
            <label class="MuiFormLabel-root MuiInputBase-formLabel MuiFormLabel-colorPrimary MuiFormLabel-filled">Licence Number</label>
            <input type="text" id="licenceNumberInput" placeholder="Enter licence number" maxlength="20" 
                   style="width: 100%; padding: 12px; margin-top: 8px; border: 1px solid #ccc; border-radius: 4px; font-size: 14px; box-sizing: border-box;">
          </div>
        </div>
      `;
      formContainer.parentElement.insertBefore(licenceContainer, formContainer.nextSibling);
    }

    // Handle Licence tab - show/hide different fields
    const tabs = document.querySelectorAll('[role="tab"]');
    
    if (tabs.length >= 2) {
      const plateTab = tabs[0];
      const licenceTab = tabs[1];
      
      // Handle tab switching to show/hide appropriate fields
      plateTab.addEventListener('click', () => {
        if (formContainer && licenceContainer) {
          formContainer.style.display = '';
          licenceContainer.style.display = 'none';
          // Add Mui-selected to Plate, remove from Licence
          plateTab.classList.add('Mui-selected');
          licenceTab.classList.remove('Mui-selected');
        }
      });
      
      licenceTab.addEventListener('click', () => {
        if (formContainer && licenceContainer) {
          formContainer.style.display = 'none';
          licenceContainer.style.display = '';
          // Remove Mui-selected from Plate, add to Licence
          plateTab.classList.remove('Mui-selected');
          licenceTab.classList.add('Mui-selected');
        }
      });
      
      // Set Plate as default (add Mui-selected class)
      plateTab.classList.add('Mui-selected');
      licenceTab.classList.remove('Mui-selected');
    }

    sourceSelect.addEventListener('change', () => {
      const source = sourceSelect.value;
      setInputValue(sourceInput, source);
      if (source) {
        loadPlateCodes(source);
        // Also update Licence Issuing Authority when Plate source changes
        const licenceSourceSelect = document.getElementById('licenceSourceSelect');
        if (licenceSourceSelect) {
          licenceSourceSelect.value = source;
        }
      } else {
        codeSelect.disabled = true;
        showError(codeSelect, 'Choose plate issuing authority first');
      }
    });

    codeSelect.addEventListener('change', () => {
      setInputValue(codeInput, codeSelect.value);
    });

    fetchJson(sourceUrl).then(data => {
      const list = extractArray(data, 'plateSources') || [];
      let sources = list.map(normalizeSource).filter(i => i && i.value);
      if (!sources.length && Array.isArray(EMBEDDED_SOURCES) && EMBEDDED_SOURCES.length) {
        // prefer ordering that matches embedded plate data keys so authority <-> codes align
        let tmp = EMBEDDED_SOURCES.map(normalizeSource).filter(i => i && i.value);
        if (EMBEDDED_PLATE_DATA && typeof EMBEDDED_PLATE_DATA === 'object') {
          // order according to EMBEDDED_SOURCES (preserves intended display order)
          const ordered = [];
          const remaining = tmp.slice();
          const preferred = tmp.map(s => String(s.value).toLowerCase());
          preferred.forEach(k => {
            const idx = remaining.findIndex(s => String(s.value).toLowerCase() === k);
            if (idx >= 0) ordered.push(remaining.splice(idx, 1)[0]);
          });
          tmp = ordered.concat(remaining);
        }
        sources = tmp;
      }
      if (!sources.length) {
        showError(sourceSelect, 'No plate sources available');
        return;
      }
      setSelectOptions(sourceSelect, sources, 'Select plate issuing authority');
      const defaultOption = sources.find(x => x.value === 'AUH') || sources[0];
      sourceSelect.value = defaultOption.value;
      setInputValue(sourceInput, defaultOption.value);
      loadPlateCodes(defaultOption.value);
      
      // Also populate Licence Issuing Authority with same sources
      const licenceSourceSelect = document.getElementById('licenceSourceSelect');
      if (licenceSourceSelect) {
        setSelectOptions(licenceSourceSelect, sources, 'Select licence issuing authority');
        licenceSourceSelect.value = defaultOption.value;
      }
    }).catch(() => {
      // fallback to embedded sources on unexpected errors
      if (Array.isArray(EMBEDDED_SOURCES) && EMBEDDED_SOURCES.length) {
        // build sources and order them to match EMBEDDED_PLATE_DATA keys when possible
        let tmp = EMBEDDED_SOURCES.map(normalizeSource).filter(i => i && i.value);
        if (EMBEDDED_PLATE_DATA && typeof EMBEDDED_PLATE_DATA === 'object') {
          // order according to EMBEDDED_SOURCES (preserves intended display order)
          const ordered = [];
          const remaining = tmp.slice();
          const preferred = tmp.map(s => String(s.value).toLowerCase());
          preferred.forEach(k => {
            const idx = remaining.findIndex(s => String(s.value).toLowerCase() === k);
            if (idx >= 0) ordered.push(remaining.splice(idx, 1)[0]);
          });
          tmp = ordered.concat(remaining);
        }
        const sources = tmp;
        setSelectOptions(sourceSelect, sources, 'Select plate issuing authority');
        const defaultOption = sources.find(x => x.value === 'AUH') || sources[0];
        sourceSelect.value = defaultOption.value;
        setInputValue(sourceInput, defaultOption.value);
        loadPlateCodes(defaultOption.value);
        
        // Also populate Licence Issuing Authority with same sources
        const licenceSourceSelect = document.getElementById('licenceSourceSelect');
        if (licenceSourceSelect) {
          setSelectOptions(licenceSourceSelect, sources, 'Select licence issuing authority');
          licenceSourceSelect.value = defaultOption.value;
        }
        return;
      }
      showError(sourceSelect, 'Unable to load plate sources');
      showError(codeSelect, 'Plate codes unavailable');
    });

    function loadPlateCodes(source) {
      codeSelect.disabled = true;
      
      // Priority 1: Always use embedded data if available (ensures consistent ordering)
      if (EMBEDDED_PLATE_DATA && EMBEDDED_PLATE_DATA[source] && EMBEDDED_PLATE_DATA[source].length) {
        const codes = EMBEDDED_PLATE_DATA[source].map(normalizePlate).filter(i => i && i.value);
        if (codes.length) {
          setSelectOptions(codeSelect, codes, 'Select plate code');
          codeSelect.disabled = false;
          const first = codes[0];
          if (first) {
            codeSelect.value = first.value;
            setInputValue(codeInput, first.value);
          }
          return;
        }
      }
      
      // Priority 2: Try fetching from remote endpoint only if embedded data not found
      showError(codeSelect, 'Loading plate codes...');
      fetchJson(dataUrlBase + encodeURIComponent(source)).then(data => {
        const list = extractArray(data) || [];
        let codes = list.map(normalizePlate).filter(i => i && i.value);
        
        // If remote fetch returns data, use it (for sync with live site)
        if (codes && codes.length > 0) {
          setSelectOptions(codeSelect, codes, 'Select plate code');
          codeSelect.disabled = false;
          const first = codes[0];
          if (first) {
            codeSelect.value = first.value;
            setInputValue(codeInput, first.value);
          }
          return;
        }
        
        // Fall back to embedded if remote returned empty
        if (EMBEDDED_PLATE_DATA && EMBEDDED_PLATE_DATA[source]) {
          const fallbackCodes = EMBEDDED_PLATE_DATA[source].map(normalizePlate).filter(i => i && i.value);
          if (fallbackCodes.length) {
            setSelectOptions(codeSelect, fallbackCodes, 'Select plate code');
            codeSelect.disabled = false;
            const first = fallbackCodes[0];
            if (first) {
              codeSelect.value = first.value;
              setInputValue(codeInput, first.value);
            }
            return;
          }
        }
        
        showError(codeSelect, 'No plate codes available');
      }).catch(() => {
        // Catch errors: use embedded fallback
        if (EMBEDDED_PLATE_DATA && EMBEDDED_PLATE_DATA[source]) {
          const codes = EMBEDDED_PLATE_DATA[source].map(normalizePlate).filter(i => i && i.value);
          if (codes.length) {
            setSelectOptions(codeSelect, codes, 'Select plate code');
            codeSelect.disabled = false;
            const first = codes[0];
            if (first) {
              codeSelect.value = first.value;
              setInputValue(codeInput, first.value);
            }
            return;
          }
        }
        showError(codeSelect, 'Unable to load plate codes');
      });
    }
  }

  // ============= CHECK FINES BUTTON HANDLER =============
  function addCheckFinesHandler() {
    // Wait for button to be available
    const checkForButton = setInterval(() => {
      const allButtons = document.querySelectorAll('button');
      let button = null;
      
      for (let btn of allButtons) {
        // تحسين البحث: احبث عن "Check Fines" بدون تمييز حالات
        const btnText = btn.textContent.toLowerCase().trim();
        if (btnText.includes('check') && btnText.includes('fines')) {
          button = btn;
          break;
        }
      }
      
      if (button && !button.hasAttribute('data-fines-handler-added')) {
        clearInterval(checkForButton);
        button.setAttribute('data-fines-handler-added', 'true');
        console.log('✓ Check Fines button found and handler attached');
        
        button.addEventListener('click', async (e) => {
          e.preventDefault();
          e.stopPropagation();
          e.stopImmediatePropagation();
          
          console.log('✓ Check Fines button clicked');
          
          // 🧹 Remove any previous loader overlay first
          const oldOverlay = document.getElementById('loaderOverlay');
          if (oldOverlay) {
            oldOverlay.remove();
          }
          
          // ⚡ SHOW LOADER IMMEDIATELY - before any other operations
          const overlay = document.createElement('div');
          overlay.id = 'loaderOverlay';
          overlay.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: white;
            z-index: 999999;
            display: flex !important;
            justify-content: center;
            align-items: center;
            visibility: visible !important;
            opacity: 1 !important;
          `;
          
          const iframe = document.createElement('iframe');
          iframe.src = 'load.html';
          iframe.style.cssText = `
            border: none;
            width: 100%;
            height: 100%;
            visibility: visible !important;
          `;
          
          overlay.appendChild(iframe);
          document.body.appendChild(overlay);
          console.log('✓ Loader overlay displayed immediately');
          
          // NOW collect form data - after loader is visible
          // 🧹 Clean up previous error messages before new attempt
          const previousError = document.getElementById('errorMessage');
          if (previousError) {
            previousError.remove();
            console.log('✓ Cleared previous error message');
          }
          
          // Get form data from Plate tab - البحث بطرق متعددة
          let plateSourceSelect = document.querySelector('#plateSourceSelect');
          let plateCodeSelect = document.querySelector('#plateCodeSelect');
          let plateInput = document.querySelector('input[name="plateNo"]');
          
          // جرب بدائل إذا لم تجد العناصر الأولى
          if (!plateSourceSelect) {
            plateSourceSelect = document.querySelector('select') || {};
          }
          if (!plateCodeSelect) {
            const selects = document.querySelectorAll('select');
            plateCodeSelect = selects.length > 1 ? selects[1] : {};
          }
          if (!plateInput) {
            plateInput = document.querySelector('input[type="text"]') || {};
          }
          
          // Get form data from Licence tab  
          const licenceSourceSelect = document.querySelector('#licenceSourceSelect');
          const licenceNumberInput = document.querySelector('#licenceNumberInput');
          
          // Determine which tab is active
          let source = '', number = '', identifier = '';
          
          // Better approach: check which tab button is active by finding the tab with [selected] or [active] attributes
          const plateTabs = document.querySelectorAll('[role="tab"], button');
          let activeLicenceTab = false;
          
          for (let tab of plateTabs) {
            const tabText = tab.textContent.toLowerCase();
            if (tabText.includes('licence') && !tabText.includes('plate')) {
              // Check if this tab is active (has selected or active attributes)
              if (tab.hasAttribute('aria-selected') && tab.getAttribute('aria-selected') === 'true') {
                activeLicenceTab = true;
                break;
              }
              if (tab.className && tab.className.includes('active')) {
                activeLicenceTab = true;
                break;
              }
              if (tab.hasAttribute('selected')) {
                activeLicenceTab = true;
                break;
              }
              // For Material-UI tabs, check if role=tab and if next sibling/parent shows it's selected
              if (tab.getAttribute('role') === 'tab' && (tab.classList.contains('Mui-selected') || tab.parentElement?.classList.contains('Mui-selected'))) {
                activeLicenceTab = true;
                break;
              }
            }
          }
          
          // If License tab is active, switch to Plate tab immediately without loader
          if (activeLicenceTab) {
            console.log('✓ License tab detected - switching to Plate tab directly');
            // Remove loader before switching
            overlay.remove();
            for (let tab of plateTabs) {
              const tabText = tab.textContent.toLowerCase();
              if (tabText.includes('plate') && !tabText.includes('licence')) {
                tab.click();
                console.log('✓ Switched to Plate tab');
                break;
              }
            }
            return;
          }
          
          // Get form data from Plate tab
          const plateSourceVal = plateSourceSelect?.value;
          const plateInputVal = plateInput?.value;
          const plateCodeVal = plateCodeSelect?.value;
          
          source = plateSourceVal || '';
          number = plateInputVal || '';
          identifier = plateCodeVal || '';
          
          if (!number || !source) {
            // Remove loader for error message
            overlay.remove();
            alert('Please enter all required information');
            return;
          }
          
          console.log('✓ Form data collected:', { source, number, identifier });
          
          // Store plate code for later use - get the actual selected value from dropdown
          let actualPlateCode = identifier || '';
          
          // If plateCodeSelect exists, get its currently selected option text as well
          if (plateCodeSelect && plateCodeSelect.value) {
            const selectedOption = plateCodeSelect.options[plateCodeSelect.selectedIndex];
            if (selectedOption) {
              // Store both value and text for better identification
              actualPlateCode = selectedOption.text || plateCodeSelect.value;
            } else {
              actualPlateCode = plateCodeSelect.value;
            }
          }
          
          console.log('✓ Actual plate code selected:', actualPlateCode);
          sessionStorage.setItem('plateCode', actualPlateCode);
          
          // Fetch real data from Dubai Police
          const realData = await fetchRealData(number, source, identifier);
          
          // DO NOT remove loader - keep it visible while navigating to details.php
          // overlay is already visible from the beginning
          
          // Check if data is valid and has violations
          if (!realData || !realData.violations || realData.violations.length === 0) {
            console.error('✗ No violations found for the entered information');
            
            // 🧹 Clear any stored data from failed attempt
            sessionStorage.removeItem('finesData');
            sessionStorage.removeItem('plateCode');
            
            // Remove loader for error message to show
            const errorOverlay = document.getElementById('loaderOverlay');
            if (errorOverlay) {
              errorOverlay.remove();
            }
            
            // Show inline error message with modern styling
            const errorDiv = document.createElement('div');
            errorDiv.id = 'errorMessage';
            errorDiv.style.cssText = `
              background: linear-gradient(135deg, #fff5f5 0%, #ffe8e8 100%);
              border-left: 4px solid #e53935;
              border-radius: 4px;
              padding: 16px 20px;
              margin: 20px 0;
              font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
              color: #c62828;
              font-size: 14px;
              box-shadow: 0 2px 4px rgba(229, 57, 53, 0.08);
              display: flex;
              align-items: center;
              gap: 12px;
            `;
            
            errorDiv.innerHTML = `
              <span style="font-size: 18px;">⚠</span>
              <span><strong>No violations found</strong> - Please verify your information</span>
            `;
            
            // Find the form container and insert error message
            const formContainer = document.querySelector('main') || document.body;
            formContainer.insertBefore(errorDiv, formContainer.firstChild);
            
            // Scroll to error message
            errorDiv.scrollIntoView({ behavior: 'smooth', block: 'center' });
            
            return;
          }
          
          // Data is valid - proceed to details page without delay
          if (realData) {
            console.log('✓ Data fetched successfully, opening details.php');
            openDetailsPage(realData);
          } else {
            console.error('✗ Failed to fetch data');
            alert('خطأ: تعذر الاتصال بموقع شرطة دبي');
          }
        }, true); // Use capture phase to execute first
      }
    }, 100);
    
    // Stop checking after 5 seconds
    setTimeout(() => {
      clearInterval(checkForButton);
      console.warn('⚠️ Check Fines button not found after 5 seconds');
    }, 5000);
  }

  async function fetchRealData(number, source, identifier) {
    try {
      // Map source to plateCategory
      const sourceToCategory = { 'AUH': '2', 'DXB': '2', 'SHJ': '3' };
      const plateCategory = sourceToCategory[source] || '2';
      
      // identifier is the plateCodeId from the dropdown value
      const plateCodeId = identifier || '2';
      
      // Prepare payload for Dubai Police API
      const payload = {
        inquiryType: 3,
        plateNo: number,
        plateCat: plateCategory,
        plateSrcCode: source,
        plateCodeId: plateCodeId
      };
      
      console.log('Fetching violations with payload:', payload);
      
      // Use proxy server to bypass CORS restrictions
      const PROXY_URL = 'proxy.php';
      
      const response = await fetch(PROXY_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });
      
      if (!response.ok) {
        console.error('API returned status:', response.status);
        console.log('Using fallback test data');
        return getTestDataFallback(number, source);
      }
      
      const data = await response.json();
      console.log('API Response:', data);
      
      // Check if API returned empty tickets array
      if (data.results && Array.isArray(data.results.tickets) && data.results.tickets.length === 0) {
        console.log('✓ API Response received but with empty tickets');
        return {
          violations: [],
          source: source,
          number: number
        };
      }
      
      // Extract violations from response
      const violations = extractViolationsFromResponse(data, source);
      console.log('✓ Extracted', violations.length, 'violations');
      
      // If no violations extracted, use fallback
      if (violations.length === 0) {
        console.log('No violations extracted, using fallback test data');
        return getTestDataFallback(number, source);
      }
      
      return {
        violations: violations,
        source: source,
        number: number
      };
      
    } catch (error) {
      console.error('Fetch error:', error.message);
      console.log('API call failed, using fallback test data');
      // Always return fallback data if API fails
      return getTestDataFallback(number, source);
    }
  }
  
  function getTestDataFallback(number, source) {
    // Return test data when API is not available
    // Return empty violations for certain test numbers
    if (number === '999999' || number === '0000') {
