          speed: '100',
          violation: 'عدم الالتزام بالمسار',
          ticketViolation: 'عدم الالتزام بالمسار الصحيح',
          amount: 800,
          fineDetails: 'التفاصيل: عدم الالتزام بالمسار الصحيح'
        },
        {
          fines: '150 AED',
